def gf2_rank(A):
    A = A.copy() % 2
    m, n = A.shape
    rank = 0; row = 0
    for col in range(n):
        pivot = None
        for r in range(row, m):
            if A[r, col] == 1:
                pivot = r; break
        if pivot is None: 
            continue
        # swap
        if pivot != row:
            A[[row,pivot]] = A[[pivot,row]]
        # eliminate other rows with 1 in this column
        for r in range(m):
            if r != row and A[r,col]==1:
                A[r,:] ^= A[row,:]
        row += 1; rank +=1
        if row==m: break
    return rank

